-- ============================================================
-- 初始化数据（INSERT IGNORE，可重复执行）
-- 若修改了初始化数据，请手动执行或删除对应记录后重启应用
--
-- 数据模型（plan4 用友式采购结算，围绕 50 笔采购订单全链路展开）：
--   6 家供应商 / 18 个物料（5 大分类）/ 50 笔订单（67 行明细）
--   → 两级审批（任务 + 流水）→ 27 张收货单（35 行明细，含分批收货）
--   → 20 张发票（含合单开票、单价差异）→ 14 笔付款（仅 MATCHED 可付款）
--   → 25 张结算单（38 行行级明细，MATCHED/PARTIAL_AMOUNT/HOLD/PARTIAL_QTY/UNMATCHED 五态）
--   → 33 行暂估（货到票未到暂估 / 票到回冲）→ 5 条四维度匹配规则
--
-- 金额口径：含税金额 = 数量 × 单价 × (1 + 税率/100)，与 MoneyUtils.calcAmount 一致；
-- 主表合计一律由明细 UPDATE 回填，避免手算出错。
--
-- 【存量库升级说明】plan4 改造新增/扩展了 po_ap_settlement 字段与
-- po_ap_settlement_item / po_match_rule / po_accrual 三张表。
-- schema.sql 使用 CREATE TABLE IF NOT EXISTS，对已存在的旧表不会自动补列；
-- 若库是在改造前初始化的，请先手工执行下列 ALTER（或直接 DROP 重建对应表）：
--   ALTER TABLE po_ap_settlement
--     ADD COLUMN match_no VARCHAR(32) NOT NULL COMMENT '结算单号' AFTER id,
--     ADD COLUMN match_batch VARCHAR(32) DEFAULT NULL COMMENT '匹配批次号' AFTER match_type,
--     ADD COLUMN match_rule_code VARCHAR(32) DEFAULT NULL COMMENT '使用的匹配规则编码' AFTER match_type,
--     ADD COLUMN currency VARCHAR(10) NOT NULL DEFAULT 'CNY' AFTER match_rule_code,
--     ADD COLUMN diff_type VARCHAR(20) DEFAULT NULL AFTER tax_diff,
--     ADD COLUMN qty_diff DECIMAL(18,3) NOT NULL DEFAULT 0 AFTER diff_amount,
--     ADD COLUMN price_diff DECIMAL(18,4) NOT NULL DEFAULT 0 AFTER qty_diff,
--     ADD COLUMN matched_by BIGINT UNSIGNED DEFAULT NULL AFTER tolerance,
--     ADD COLUMN matched_time DATETIME DEFAULT NULL AFTER matched_by,
--     ADD COLUMN hold_reason VARCHAR(500) DEFAULT NULL AFTER matched_time,
--     ADD COLUMN resolution VARCHAR(200) DEFAULT NULL AFTER hold_reason,
--     ADD COLUMN version INT NOT NULL DEFAULT 0 AFTER resolution,
--     ADD UNIQUE KEY uk_match_no (match_no),
--     ADD KEY idx_status (match_status),
--     ADD KEY idx_matched_time (matched_time);
-- ============================================================

-- 【存量库升级】po_invoice 新增 invoice_type / related_invoice_id / related_invoice_no
-- （红冲+重开：红字发票抵消原蓝票，一收货单允许多张发票，匹配按订单净额）
-- MySQL 无 ADD COLUMN IF NOT EXISTS，用 information_schema 守卫幂等执行：
SET @c1 = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'po_invoice' AND COLUMN_NAME = 'invoice_type');
SET @s1 = IF(@c1 = 0, "ALTER TABLE po_invoice ADD COLUMN invoice_type VARCHAR(8) NOT NULL DEFAULT 'BLUE' COMMENT 'BLUE 蓝字/RED 红字' AFTER total_amount", 'SELECT 1');
PREPARE stmt1 FROM @s1; EXECUTE stmt1; DEALLOCATE PREPARE stmt1;

SET @c2 = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'po_invoice' AND COLUMN_NAME = 'related_invoice_id');
SET @s2 = IF(@c2 = 0, "ALTER TABLE po_invoice ADD COLUMN related_invoice_id BIGINT UNSIGNED DEFAULT NULL COMMENT '红蓝关联：红字发票指向原发票' AFTER invoice_type", 'SELECT 1');
PREPARE stmt2 FROM @s2; EXECUTE stmt2; DEALLOCATE PREPARE stmt2;

SET @c3 = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'po_invoice' AND COLUMN_NAME = 'related_invoice_no');
SET @s3 = IF(@c3 = 0, "ALTER TABLE po_invoice ADD COLUMN related_invoice_no VARCHAR(32) DEFAULT NULL COMMENT '被红冲原发票号' AFTER related_invoice_id", 'SELECT 1');
PREPARE stmt3 FROM @s3; EXECUTE stmt3; DEALLOCATE PREPARE stmt3;

UPDATE po_invoice SET invoice_type = 'BLUE' WHERE invoice_type IS NULL OR invoice_type = '';

