-- ---------------- 清理段（先删后插，保证可重复执行且不残留旧口径数据） ----------------
-- 覆盖三套历史 id 段：早期 demo（1~8）、plan4 首批（9001~9050 旧值）、300 单扩展段（10001~10300）
DELETE si FROM po_ap_settlement_item si
  JOIN po_ap_settlement s ON s.id = si.settlement_id
 WHERE s.order_id IN (1, 2, 7, 8) OR s.order_id BETWEEN 9001 AND 9050 OR s.order_id BETWEEN 10001 AND 10300;
DELETE FROM po_ap_settlement
 WHERE order_id IN (1, 2, 7, 8) OR order_id BETWEEN 9001 AND 9050 OR order_id BETWEEN 10001 AND 10300;
DELETE FROM po_ap_settlement
 WHERE match_status NOT IN ('MATCHED', 'PARTIAL_QTY', 'PARTIAL_AMOUNT', 'HOLD', 'UNMATCHED', 'CLOSED', 'REVERSED')
    OR match_type IS NULL OR match_type = ''
    OR match_no IS NULL OR match_no = '';
DELETE FROM po_accrual WHERE order_id IN (1, 2, 7, 8) OR order_id BETWEEN 9001 AND 9050 OR order_id BETWEEN 10001 AND 10300;
DELETE FROM agent_alert WHERE rule_code = 'INVOICE_MISMATCH';
DELETE FROM agent_alert_action WHERE alert_id NOT IN (SELECT alert_id FROM agent_alert);
DELETE FROM po_payment  WHERE id BETWEEN 1 AND 4 OR id BETWEEN 63001 AND 63300 OR id BETWEEN 7301 AND 7399;
DELETE FROM po_invoice  WHERE id BETWEEN 1 AND 4 OR id BETWEEN 62001 AND 62300 OR id BETWEEN 7201 AND 7299;
DELETE FROM po_receipt_item WHERE receipt_id BETWEEN 1 AND 4 OR receipt_id BETWEEN 60001 AND 60300 OR receipt_id BETWEEN 7001 AND 7099;
DELETE FROM po_receipt  WHERE id BETWEEN 1 AND 4 OR id BETWEEN 60001 AND 60300 OR id BETWEEN 7001 AND 7099;
DELETE FROM po_order_item WHERE id BETWEEN 9101 AND 9167 OR id BETWEEN 50001 AND 50300;
DELETE FROM po_order   WHERE id BETWEEN 1 AND 8 OR id BETWEEN 9001 AND 9050 OR id BETWEEN 10001 AND 10300;
DELETE FROM po_approval_task WHERE order_id BETWEEN 9001 AND 9050 OR order_id BETWEEN 10001 AND 10300;
DELETE FROM po_approval_log  WHERE order_id BETWEEN 9001 AND 9050 OR order_id BETWEEN 10001 AND 10300;
DELETE FROM po_inventory WHERE material_id BETWEEN 2001 AND 2099;
DELETE FROM po_match_rule;

