-- 明细含税金额：数量 × 单价 × (1 + 税率/100)，保留 2 位（与 MoneyUtils.calcAmount 口径一致）
UPDATE po_order_item
   SET amount = ROUND(qty * price * (1 + tax_rate / 100), 2)
 WHERE id BETWEEN 9101 AND 9167;

-- 主表合计：由明细汇总回填，保证与明细口径一致
UPDATE po_order o
   SET o.total_qty    = IFNULL((SELECT SUM(i.qty)    FROM po_order_item i WHERE i.order_id = o.id), 0),
       o.total_amount = IFNULL((SELECT SUM(i.amount) FROM po_order_item i WHERE i.order_id = o.id), 0)
 WHERE o.id BETWEEN 9001 AND 9050;

-- ---------------- 审批任务（由订单状态推导：草稿无任务，保证与订单状态一致） ----------------
-- 9023/9039/9040/9041 一级待审（current_node=1）；9013~9018 一级已过、二级待审（current_node=2）
INSERT IGNORE INTO po_approval_task
 (id, order_id, node_seq, node_role, node_name, approver_id, status, approve_time, opinion, version, create_time)
SELECT 9600 + (o.id - 9000) * 2 - 1, o.id, 1, 'PURCHASE_MANAGER', '采购经理审批', 4,
       CASE
         WHEN o.status = 'REJECTED' THEN 'REJECTED'
         WHEN o.status = 'CANCELED' THEN 'INVALID'
         WHEN o.id IN (9023, 9039, 9040, 9041) THEN 'PENDING'
         ELSE 'APPROVED'
       END,
       CASE WHEN o.status IN ('APPROVED', 'REJECTED')
            THEN TIMESTAMP(DATE_ADD(o.submit_time, INTERVAL 1 DAY), '14:00:00') ELSE NULL END,
       CASE o.status
         WHEN 'REJECTED' THEN CASE o.id
                                 WHEN 9009 THEN '单价高于框架价，请重新询价'
                                 WHEN 9042 THEN '现有设备仍可满足使用，暂不更换'
                                 WHEN 9048 THEN '供应商产能不足，交期无法保证'
                                 WHEN 9049 THEN '原厂延保可覆盖，暂不单独采购'
                                 ELSE '需求不合理，请重新评估' END
         ELSE '同意，采购需求合理'
       END,
       1, o.submit_time
  FROM po_order o
 WHERE o.id BETWEEN 9001 AND 9050 AND o.status <> 'DRAFT'
UNION ALL
SELECT 9600 + (o.id - 9000) * 2, o.id, 2, 'DIRECTOR', '总监审批', 5,
       CASE
         WHEN o.status = 'APPROVED' THEN 'APPROVED'
         WHEN o.status IN ('REJECTED', 'CANCELED') THEN 'INVALID'
         WHEN o.id IN (9023, 9039, 9040, 9041) THEN 'WAITING'
         ELSE 'PENDING'
       END,
       CASE WHEN o.status = 'APPROVED'
            THEN TIMESTAMP(DATE_ADD(o.submit_time, INTERVAL 2 DAY), '16:30:00') ELSE NULL END,
       CASE WHEN o.status = 'APPROVED' THEN '同意，按预算执行' ELSE NULL END,
       1, o.submit_time
  FROM po_order o
 WHERE o.id BETWEEN 9001 AND 9050 AND o.status <> 'DRAFT';

-- ---------------- 审批流水（提交 + 节点审批，与任务/订单状态一致） ----------------
INSERT IGNORE INTO po_approval_log
 (id, order_id, node_seq, node_role, operator_id, action, from_status, to_status, opinion, operate_time)
SELECT 9700 + (o.id - 9000), o.id, NULL, NULL, o.buyer_id, 'SUBMIT', 'DRAFT', 'APPROVING', '提交审批', o.submit_time
  FROM po_order o
 WHERE o.id BETWEEN 9001 AND 9050 AND o.status <> 'DRAFT';

INSERT IGNORE INTO po_approval_log
 (id, order_id, node_seq, node_role, operator_id, action, from_status, to_status, opinion, operate_time)
SELECT 9800 + (t.id - 9600), t.order_id, t.node_seq, t.node_role, t.approver_id,
       CASE WHEN t.status = 'REJECTED' THEN 'REJECT' ELSE 'APPROVE' END,
       'APPROVING',
       CASE t.node_seq WHEN 1 THEN 'APPROVING' ELSE 'APPROVED' END,
       t.opinion, t.approve_time
  FROM po_approval_task t
 WHERE t.order_id BETWEEN 9001 AND 9050 AND t.status IN ('APPROVED', 'REJECTED') AND t.approve_time IS NOT NULL;

-- ---------------- 库存（18 个物料，数量 = 累计入库，低于安全库存的触发库存预警） ----------------
