UPDATE po_receipt_item
   SET tax_amount = ROUND(received_qty * unit_price * tax_rate / 100, 2),
       amount     = ROUND(received_qty * unit_price * (1 + tax_rate / 100), 2)
 WHERE id BETWEEN 7101 AND 7135;

UPDATE po_receipt r
   SET r.total_qty    = IFNULL((SELECT SUM(i.received_qty) FROM po_receipt_item i WHERE i.receipt_id = r.id), 0),
       r.total_amount = IFNULL((SELECT SUM(i.amount)       FROM po_receipt_item i WHERE i.receipt_id = r.id), 0)
 WHERE r.id BETWEEN 7001 AND 7027;

