-- 拆分不含税金额与税额：不含税 = 价税合计 / 1.13，税额 = 不含税 × 13%
UPDATE po_invoice
   SET invoice_amount = ROUND(total_amount / 1.13, 2),
       tax_amount     = ROUND(total_amount / 1.13 * 0.13, 2)
 WHERE id BETWEEN 7201 AND 7220;

