-- 差异金额 = 发票 - 收货（UNMATCHED 票未到不计算差异）
UPDATE po_ap_settlement
   SET diff_amount = invoice_amount - receipt_amount
 WHERE match_status <> 'UNMATCHED';

-- 演示等待态：9003 显示器单价上浮 1.5% 已登记「退票重开」→ WAITING_INVOICE
-- （工作台“处理中”分组、预警自动退出、付款继续拦截；供应商重开发票并核对后由事件驱动重新匹配推回正常流程）
UPDATE po_ap_settlement
   SET match_status = 'WAITING_INVOICE',
       resolution  = 'REDO_INVOICE',
       diff_amount = 610.20,
       hold_reason = '已登记【退票重开】，等待供应商作废原票并重新开具｜登记人：3｜登记时间：2026-08-02 10:00｜处理意见：显示器单价上浮 1.5%，已通知供应商按合同价 1200 元/台重开'
 WHERE match_no = 'MATCH202610010003';

