-- ---------------- 清理指向失效记录的预警 ----------------
-- 种子重放采用先删后插，结算单/暂估的自增 ID 会变化；
-- 历史预警若指向已不存在的记录会成为“孤儿预警”（下次扫描还会重复生成），这里统一清理。
-- 启动 1 分钟后的定时扫描会按新 ID 重建，预警中心不会长时间为空。
DELETE FROM agent_alert_action
 WHERE alert_id IN (
   SELECT alert_id FROM agent_alert
    WHERE rule_code IN ('INVOICE_MISMATCH', 'ACCRUAL_PENDING')
      AND (   (rule_code = 'INVOICE_MISMATCH' AND ref_id NOT IN (SELECT id FROM po_ap_settlement))
           OR (rule_code = 'ACCRUAL_PENDING'  AND ref_id NOT IN (SELECT id FROM po_accrual)))
 );
DELETE FROM agent_alert
 WHERE rule_code IN ('INVOICE_MISMATCH', 'ACCRUAL_PENDING')
   AND (   (rule_code = 'INVOICE_MISMATCH' AND ref_id NOT IN (SELECT id FROM po_ap_settlement))
        OR (rule_code = 'ACCRUAL_PENDING'  AND ref_id NOT IN (SELECT id FROM po_accrual)));
